// Função Netlify que recebe o webhook email.received do Resend e encaminha a
// mensagem para FORWARD_TO. Só aceita chamadas assinadas com RESEND_WEBHOOK_SECRET.
import { createHmac, timingSafeEqual } from 'node:crypto'

const API = 'https://api.resend.com'
const SIGNATURE_MAX_AGE = 300

export const config = { path: '/api/inbound' }

export default async function handler(request) {
  if (request.method !== 'POST') {
    return new Response('Method Not Allowed', { status: 405, headers: { Allow: 'POST' } })
  }

  const body = await request.text()
  if (!validSignature(request.headers, body)) return new Response('Unauthorized', { status: 401 })

  const event = JSON.parse(body)
  if (event.type !== 'email.received') return new Response(null, { status: 204 })

  try {
    await forward(event.data.email_id)
  } catch (error) {
    // Erro faz o Resend tentar de novo; a chave de idempotência evita duplicar.
    console.error('[inbound] encaminhamento falhou:', error)
    return new Response('Bad Gateway', { status: 502 })
  }
  return new Response(null, { status: 204 })
}

// Assinatura do Svix: HMAC-SHA256 de "id.timestamp.corpo", com o segredo em base64.
function validSignature(headers, body) {
  const id = headers.get('svix-id')
  const timestamp = headers.get('svix-timestamp')
  const signatures = headers.get('svix-signature')
  const secret = process.env.RESEND_WEBHOOK_SECRET
  if (!id || !timestamp || !signatures || !secret) return false
  if (Math.abs(Date.now() / 1000 - Number(timestamp)) > SIGNATURE_MAX_AGE) return false

  const expected = createHmac('sha256', Buffer.from(secret.replace(/^whsec_/, ''), 'base64'))
    .update(`${id}.${timestamp}.${body}`)
    .digest()
  return signatures.split(' ').some((entry) => {
    const [version, value = ''] = entry.split(',')
    const received = Buffer.from(value, 'base64')
    return version === 'v1' && received.length === expected.length && timingSafeEqual(received, expected)
  })
}

async function forward(emailId) {
  const { RESEND_INBOUND_API_KEY, FORWARD_TO, FORWARD_FROM = 'contact@thomasdev.xyz' } = process.env
  if (!RESEND_INBOUND_API_KEY || !FORWARD_TO) throw new Error('RESEND_INBOUND_API_KEY ou FORWARD_TO ausente')

  const api = async (path, init = {}) => {
    const response = await fetch(`${API}${path}`, {
      ...init,
      headers: { Authorization: `Bearer ${RESEND_INBOUND_API_KEY}`, 'Content-Type': 'application/json', ...init.headers },
    })
    if (!response.ok) throw new Error(`Resend ${response.status}: ${await response.text()}`)
    return response.json()
  }

  const email = await api(`/emails/receiving/${emailId}`)
  const { data: attachments = [] } = await api(`/emails/receiving/${emailId}/attachments`)
  // Endereço no nome de exibição parece falsificação para o Gmail: fica só o nome.
  const sender = String(email.from ?? '').replace(/<.*>/, '').replace(/@.*/, '').replace(/[^\p{L}\p{N}.+\- ]/gu, ' ').replace(/\s+/g, ' ').trim() || 'Contato'

  await api('/emails', {
    method: 'POST',
    headers: { 'Idempotency-Key': `inbound-${emailId}` },
    body: JSON.stringify({
      from: `${sender} via thomasdev <${FORWARD_FROM}>`,
      to: FORWARD_TO,
      reply_to: email.from,
      subject: email.subject || '(sem assunto)',
      html: email.html || undefined,
      text: email.text || (email.html ? undefined : ' '),
      attachments: attachments.map((file) => ({
        filename: file.filename,
        path: file.download_url,
        content_type: file.content_type,
        content_id: file.content_id?.replace(/^<|>$/g, '') || undefined,
      })),
    }),
  })
}
// Função Netlify (API v2: recebe Request, devolve Response) do formulário de
// contato. Responde HTML: um fragmento para o htmx, ou um redirect com âncora
// para quem está sem JavaScript. Envia a notificação direto na API do Resend.
// Nunca envie e-mail ao endereço digitado no formulário: qualquer um poderia
// usar o site para mandar spam a terceiros pelo domínio.
import { contactMessages, CONTACT_LOCALES, escapeHtml, successBox, errorBox } from '../src/lib/contact-messages.mjs'
import { fill } from '../src/lib/text.js'

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const MAX_LENGTH = { nome: 100, email: 254, telefone: 30, cidade: 100, mensagem: 5000 }

// O limite do Netlify exige `path`, que substitui a rota /.netlify/functions/contact.
export const config = {
  path: '/api/contact',
  rateLimit: { windowLimit: 5, windowSize: 60, aggregateBy: ['ip', 'domain'] },
}

export default async function handler(request) {
  if (request.method !== 'POST') {
    return new Response('Method Not Allowed', { status: 405, headers: { Allow: 'POST' } })
  }

  const form = await request.formData()
  const line = (name) => String(form.get(name) ?? '').replace(/\s+/g, ' ').trim()
  const locale = CONTACT_LOCALES.includes(line('locale')) ? line('locale') : 'pt'
  const messages = contactMessages[locale]
  const isHtmx = request.headers.get('hx-request') === 'true'
  const backTo = `${locale === 'pt' ? '' : `/${locale}`}/contato`

  const html = (body, status = 200, headers = {}) =>
    new Response(body, { status, headers: { 'Content-Type': 'text/html; charset=utf-8', ...headers } })
  const redirect = (hash) => new Response(null, { status: 303, headers: { Location: `${backTo}#${hash}` } })
  const success = () =>
    isHtmx ? html(successBox(locale), 200, { 'HX-Retarget': '#contact-form', 'HX-Reswap': 'outerHTML' }) : redirect('enviado')
  const failure = (text, status) => (isHtmx ? html(errorBox(locale, text), status) : redirect('erro'))

  // Honeypot: só robôs preenchem o campo escondido. Finge sucesso e descarta.
  if (line('bot-field')) return success()

  const data = {
    nome: line('nome'),
    email: line('email'),
    telefone: line('telefone'),
    cidade: line('cidade'),
    mensagem: String(form.get('mensagem') ?? '').trim(),
  }
  if (!data.nome || !data.email || !data.mensagem) return failure(messages.error_required, 422)
  if (!EMAIL_RE.test(data.email)) return failure(messages.error_email, 422)
  if (Object.entries(MAX_LENGTH).some(([name, max]) => data[name].length > max)) return failure(messages.error_length, 422)
  if (!(await humanVerified(form.get('cf-turnstile-response'), request))) return failure(messages.error_captcha, 403)

  try {
    await sendMail({
      to: process.env.CONTACT_TO || 'contact@thomasdev.xyz',
      reply_to: data.email,
      subject: fill(messages.notify_subject, data),
      html: notifyHtml(data),
    })
  } catch (error) {
    console.error('[contact] envio falhou:', error)
    return failure(messages.error_server, 502)
  }
  return success()
}

// Sem segredo (dev, testes) não há verificação. Falha da Cloudflare recusa o envio.
async function humanVerified(token, request) {
  const secret = process.env.TURNSTILE_SECRET_KEY
  if (!secret) return true
  if (!token) return false
  const body = new URLSearchParams({ secret, response: String(token) })
  const ip = request.headers.get('x-nf-client-connection-ip')
  if (ip) body.set('remoteip', ip)
  try {
    const response = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', { method: 'POST', body })
    return (await response.json()).success === true
  } catch (error) {
    console.error('[contact] Turnstile falhou:', error)
    return false
  }
}

async function sendMail(fields) {
  const { RESEND_API_KEY, RESEND_FROM = 'Thomas Dev <contact@thomasdev.xyz>' } = process.env

  // Sem chave (dev, testes, preview sem env): registra e segue como sucesso.
  if (!RESEND_API_KEY) {
    console.log('[contact] RESEND_API_KEY ausente; e-mail não enviado:', fields.subject)
    return
  }

  const response = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: `Bearer ${RESEND_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ from: RESEND_FROM, ...fields }),
  })
  if (!response.ok) throw new Error(`Resend ${response.status}: ${await response.text()}`)
}

function notifyHtml(data) {
  const rows = [
    ['Nome', data.nome],
    ['E-mail', data.email],
    ['Telefone', data.telefone],
    ['Cidade', data.cidade],
  ]
    .filter(([, value]) => value)
    .map(([label, value]) => `<tr><th align="left" style="padding:4px 16px 4px 0">${label}</th><td>${escapeHtml(value)}</td></tr>`)
    .join('')
  return `<table>${rows}</table><p style="white-space:pre-wrap">${escapeHtml(data.mensagem)}</p>`
}
